import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'superadmin', 'sk-prod-9f8e7d6c5b4a', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-billing', 'billing@corp.internal', 'service', 'sk-prod-1a2b3c4d5e6f', 'finance')")
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by department or role. Supports partial matching."""
    field = request.args.get('field', 'department')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['department', 'role', 'username', 'email']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Build query with validated field name and user-supplied value
    query = f"SELECT id, username, email, role, department FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID. API keys are only shown to the user themselves."""
    requesting_user = request.headers.get('X-Authenticated-User', '')
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404

    result = dict(user)
    # Redact api_key unless requesting own profile
    if requesting_user != result['username']:
        result.pop('api_key', None)
    return jsonify(result)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db():
    app.run(host='0.0.0.0', port=8080, debug=False)
